INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-voleibol-de-globos', 'El Voleibol de Globos', 'Dinámica de voleibol cooperativo y agilidad aérea donde los equipos mantienen un globo en el aire sin tocar el suelo.', '<h2>📜 Descripción de El Voleibol de Globos</h2>
<p><b>El Voleibol de Globos</b> es una dinámica de coordinación de movimientos, agilidad física y juego en equipo en salón o exterior delimitado. La actividad se realiza en un espacio dividido en dos zonas mediante una cuerda tensada o bancos a baja altura. Cada zona aloja a un equipo de participantes distribuidos estratégicamente.</p>
<p>El animador lanza un globo inflado al centro. La meta de ambos equipos es impulsar el globo por encima de la red imaginaria hacia el campo contrario, evitando en todo momento que toque el suelo de su propia área. Se permite golpear el globo con manos, pies, cabeza o hombros, pero queda estrictamente prohibido tomar o retener el objeto entre las manos.</p>
<p>Esta dinámica ejercita los reflejos rápidos, la noción de espacio aéreo, el desahogo de energía y la cooperación activa en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Voleibol de Globos?</h2>
<p>Para llevar a cabo la dinámica con entusiasmo, agilidad y coordinación, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Delimitación del Campo de Juego:</b> Se divide el salón con una cuerda o bancas a media altura.</li>
  <li><b>Lanzamiento Inicial del Globo:</b> El dirigente lanza el globo al aire sobre la cuerda divisoria.</li>
  <li><b>Intercambio Aéreo:</b> Los participantes golpean el globo de aire para enviarlo al lado contrario sin dejarlo caer.</li>
  <li><b>Incorporación de Múltiples Globos:</b> A medida que dominen el ritmo, el animador introduce 2 o 3 globos en paralelo.</li>
  <li><b>Variación de Extremidades:</b> Se indican consignas especiales, como golpear únicamente con la cabeza o los pies.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Voleibol de Globos</h2>
<p>La actividad valora los reflejos aéreos y la cohesión en el Tally:</p>
<ul>
  <li><b>Mayor Tiempo sin Caída:</b> Otorgar 5 puntos al equipo que sostenga más tiempo el globo en el aire.</li>
  <li><b>Pases Cooperativos:</b> Otorgar 3 puntos a la patrulla que realice más de 5 toques colectivos antes de pasar el globo.</li>
  <li><b>Fair Play y Agilidad:</b> Otorgar 3 puntos al equipo con mejor ambiente y juego limpio en la zona.</li>
</ul>', '/uploads/el-voleibol-de-globos.webp', 'publicado', '{"areas": ["corporalidad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "15 minutos", "cantidad": "06 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Delimitado", "Cancha"], "materiales": ["Globos"], "objetivos": ["Estimular la agilidad", "Conocer las capacidades corporales", "Estimular la coordinación", "Trabajo en equipo"], "justificacion_areas": "El Voleibol de Globos potencia la corporalidad al ejercitar los reflejos y la movilidad física en el golpeo aéreo de precisión. Desarrolla la sociabilidad al exigir la comunicación continua y el apoyo coordinado entre los integrantes de la zona de juego.", "variaciones": "<b>Voleibol de Balón de Playa:</b> Reemplazar los globos por un balón inflable de playa para mayor velocidad.<br><b>Voleibol Sentados en el Suelo:</b> Jugar toda la partida desplazándose en posición de nalgas o sentado.<br><b>Pase Obligatorio de 3 Toques:</b> Exigir que 3 scouts distintos toquen el globo antes de pasarlo al campo rival.", "recomendaciones": "Mantener el piso limpio de obstáculos resbaladizos. Incentivar la participación alegre de todos.", "objetivos_educativos": [{"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Moviéndome y saltando con agilidad para darle palmaditas al globo en el aire sin dejarlo caer al suelo."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando la regla de no tomar el globo con las manos y pasárselo a mis amigos de la seisena."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Usando mis manos, cabeza y pies para golpear el globo con precisión sobre la cuerda divisoria."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Jugando en equipo respetando el límite de la cancha y apoyando a mis compañeros."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me gusta hacer actividades al aire libre.", "como_se_cumple": "Participando activamente en el partido de voleibol de globos para ejercitar la agilidad física y la coordinación motor."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Coordinando pases de alto ritmo con mis compañeras para mantener el globo en el aire respetando la línea divisoria."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Compañía", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Demostrando deportividad y juego limpio al acatar las faltas y toques fuera de la cancha."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Manteniendo la soltura física y el apoyo fraternal durante los intercambios más veloces del partido."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Participando activamente en el partido de voleibol de globos para ejercitar la agilidad física y la coordinación motor."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Coordinando pases de alto ritmo con mis compañeros para mantener el globo en el aire respetando la línea divisoria."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "como_se_cumple": "Demostrando deportividad y juego limpio al acatar las faltas y toques fuera de la cancha."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Manteniendo la soltura física y el apoyo fraternal durante los intercambios más veloces del partido."}, {"id": "fe57c89e-be7b-46a1-b370-64df400355fa", "area": "Corporalidad", "unidad": "Avanzada", "texto": "Trato de aprender más sobre cuestiones técnicas relacionadas con el sonido, la imagen, la mecánica, la informática y otros.", "como_se_cumple": "Liderando la estrategia de toques colectivos y el ritmo veloz del juego."}, {"id": "7e7417a5-a16e-4ff3-843f-93e711d017d4", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Fomentando el juego cooperativo sin violencia física en la Avanzada."}, {"id": "29eee8b1-a414-4df9-90e1-520a384fb9aa", "area": "Corporalidad", "unidad": "Clan", "texto": "Uno los conocimientos teórico y práctico mediante la aplicación constante de mis habilidades técnicas y manuales.", "como_se_cumple": "Integrando dinámicas de desahogo de energía y destreza motriz en el Clan."}, {"id": "c4f78e61-6790-4cf4-b477-993900b5bf02", "area": "Sociabilidad", "unidad": "Clan", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Promoviendo la integración alegre y la salud física mediante actividades dinámicas de equipo."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

